def get_components_4color(grid, color):
    h, w = len(grid), len(grid[0])
    visited_color = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == color and (r, cq) not in visited_color:
                comp = get_component_4(grid, r, c, color)
                comps.append(comp)
                visited_color.update(comp)
    return comps

def get_component_4(grid, start_r, start_c, target_color):
    h, w = len(grid), len(grid[0])
    comp = []
    queue = [(start_r, start_c)]
    visited = {(start_r, start_c)}
    while queue:
        r, cq = queue.pop(0)
        comp.append((r, c))
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == target_color and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc))
    return comp

# Simpler: for each cell of target color, do BFS
def get_components(grid, target_color, h, w):
    visited = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_color and (r, c) not in visited:
                comp = []
                stack = [(r, c)]
                visited.add((r, c))
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == target_color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            stack.append((nr, nc))
                comps.append(comp)
    return comps

